+        ["empty project API key", { posthog: { projectApiKey: "", apiHost: "bar" } }],
+        ["missing API host", { posthog: { projectApiKey: "foo" } }],
+        ["empty API host", { posthog: { projectApiKey: "foo", apiHost: "" } }],
